{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "Insilos có hỗ trợ triển khai hoàn toàn Offline (Air-Gapped) không?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Có. Insilos hỗ trợ triển khai 100% On-Premises và Air-Gapped độc lập, đáp ứng nghiêm ngặt các quy chuẩn an toàn lưới điện EVN, quân sự và ngân hàng Nhà nước, không gửi bất kỳ byte dữ liệu nào ra Internet."
            }
        },
        {
            "@type": "Question",
            "name": "Chi phí bản quyền và mô hình tính giá được xác định như thế nào?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Insilos áp dụng mô hình cấp phép module linh hoạt theo nhu cầu vận hành thực tế (Vertical IDP, Knowledge Graph, Trade Compliance, FSM) kết hợp khối lượng chứng từ xử lý hàng tháng, giúp doanh nghiệp tối ưu chi phí và hoàn vốn trong 3-6 tháng."
            }
        },
        {
            "@type": "Question",
            "name": "Thời gian triển khai một dự án PoC hoặc Pilot thường kéo dài bao lâu?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Một đợt triển khai Pilot chuẩn của Insilos diễn ra trong 2-4 tuần với dữ liệu thực nghiệm của khách hàng để chứng minh tỷ lệ STP vượt 97.4% và độ trễ phản hồi dưới 15ms trước khi nghiệm thu."
            }
        },
        {
            "@type": "Question",
            "name": "Hệ thống có tuân thủ chuẩn kế toán Thông tư 200 và hóa đơn Thông tư 78 không?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "100% tuân thủ. Insilos tích hợp sẵn các luật đối soát kế toán Thông tư 200/2014/TT-BTC, chuẩn hóa hóa đơn điện tử Thông tư 78/2021/TT-BTC và đối soát 3 chiều tự động giữa PO, B/L và Hóa đơn."
            }
        },
        {
            "@type": "Question",
            "name": "Chính sách cam kết SLA thời gian sẵn sàng (Uptime) ra sao?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Insilos cam kết SLA thời gian sẵn sàng 99.8% đối với môi trường sản xuất công nghiệp trọng yếu, hỗ trợ kỹ thuật 24/7/365 và thời gian phản hồi sự cố mức độ nghiêm trọng P1 dưới 15 phút."
            }
        },
        {
            "@type": "Question",
            "name": "Doanh nghiệp có quyền sở hữu mô hình AI và đồ thị tri thức sau khi huấn luyện không?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Tuyệt đối có. Khách hàng sở hữu 100% bản quyền mô hình, trọng số fine-tuned và ontology đồ thị tri thức được xây dựng trên dữ liệu của doanh nghiệp, cam kết không bị khóa vào nhà cung cấp độc quyền (Zero Lock-In)."
            }
        }
    ]
}

